package ctrip

import (
	"ctrip-cli/browser"
	"encoding/json"
	"fmt"
	"time"
)

type Attraction struct {
	Name         string   `json:"name"`
	PoiID        int      `json:"poi_id"`
	Score        float64  `json:"score"`
	ReviewCount  int      `json:"review_count"`
	Price        float64  `json:"price"`
	PriceDesc    string   `json:"price_desc"`
	IsFree       bool     `json:"is_free"`
	Address      string   `json:"address,omitempty"`
	Distance     string   `json:"distance,omitempty"`
	Tags         []string `json:"tags,omitempty"`
	ShortDesc    string   `json:"short_desc,omitempty"`
	CategoryInfo string   `json:"category_info,omitempty"`
	URL          string   `json:"url"`
	CoverImage   string   `json:"cover_image,omitempty"`
}

type AttractionSearchResult struct {
	Attractions []Attraction `json:"attractions"`
	TotalCount  int          `json:"total_count"`
	District    string       `json:"district"`
}

func SearchAttractions(client *browser.Client, destination string, limit int) (*AttractionSearchResult, error) {
	u := fmt.Sprintf("https://you.ctrip.com/sight/%s.html", destination)

	if err := client.Navigate(u); err != nil {
		return nil, fmt.Errorf("navigate: %w", err)
	}

	time.Sleep(4 * time.Second)

	js := `(function(){
		var pp = window.__NEXT_DATA__ && window.__NEXT_DATA__.props && window.__NEXT_DATA__.props.pageProps;
		if (!pp || !pp.initialState) return JSON.stringify({error: "no_data"});
		var s = pp.initialState;
		var ld = s.listInitData || {};
		var al = ld.attractionList || [];
		var district = ld.districtName || "";
		var total = ld.totalCount || al.length;
		var attractions = al.map(function(a){
			var c = a.card || {};
			return {
				name: c.poiName || "",
				poi_id: c.poiId || 0,
				score: c.commentScore || 0,
				review_count: c.commentCount || 0,
				price: c.price || 0,
				price_desc: c.isFree ? "免费" : (c.priceTypeDesc ? ("¥" + c.price + " " + c.priceTypeDesc) : ""),
				is_free: c.isFree || false,
				distance: c.distanceStr || "",
				tags: (c.tagNameList || []),
				short_desc: (c.shortFeatures || [])[0] || "",
				category_info: c.sightCategoryInfo || "",
				url: c.detailUrl || "",
				cover_image: c.dynamicCoverImageUrl || c.coverImageUrl || ""
			};
		});
		return JSON.stringify({attractions: attractions, total_count: total, district: district});
	})()`

	raw, err := client.EvaluateJSON(js)
	if err != nil {
		return nil, fmt.Errorf("evaluate: %w", err)
	}

	var check struct {
		Error string `json:"error"`
	}
	json.Unmarshal(raw, &check)
	if check.Error != "" {
		return nil, fmt.Errorf("page data not available: %s", check.Error)
	}

	var result AttractionSearchResult
	if err := json.Unmarshal(raw, &result); err != nil {
		return nil, fmt.Errorf("parse: %w", err)
	}

	if limit > 0 && len(result.Attractions) > limit {
		result.Attractions = result.Attractions[:limit]
	}

	return &result, nil
}

package cmd

import (
	"errors"
	"os"
	"strings"

	"github.com/spf13/cobra"

	"google-cli/browser"
	"google-cli/google"
	"google-cli/output"
)

func init() {
	searchCmd := &cobra.Command{
		Use:           "search <query>",
		Short:         "Search Google and return structured results",
		SilenceUsage:  true,
		SilenceErrors: true,
		Run: func(cmd *cobra.Command, args []string) {
			if len(args) < 1 {
				output.Error("missing_args", "search requires a query: google-cli search <query>")
				os.Exit(1)
			}
			query := strings.Join(args, " ")
			limit, _ := cmd.Flags().GetInt("limit")
			hl, _ := cmd.Flags().GetString("hl")

			client := withActivateMode(browser.NewClient("google-cli"))

			// Fail fast if the daemon / extension isn't ready.
			st, err := client.Status()
			if err != nil {
				output.Error("daemon_unreachable", err.Error())
				os.Exit(1)
			}
			if !st.Running {
				output.Error("daemon_not_running", "kimi-webbridge daemon is not running (open the Kimi Desktop App)")
				os.Exit(1)
			}
			if !st.ExtensionConnected {
				output.Error("extension_not_connected", "Chrome WebBridge extension is not connected (see https://www.kimi.com/features/webbridge)")
				os.Exit(1)
			}

			results, err := google.FetchSearch(client, query, limit, hl)
			if err != nil {
				var consent google.ErrConsentRequired
				if errors.As(err, &consent) {
					output.Error("consent_required", err.Error())
				} else if strings.Contains(err.Error(), "daemon unreachable") {
					output.Error("daemon_unreachable", err.Error())
				} else {
					output.Error("search_failed", err.Error())
				}
				os.Exit(1)
			}
			if len(results) == 0 {
				output.Error("no_results", "google returned no parseable results (selectors may have drifted — see ARCHAEOLOGY.md)")
				os.Exit(1)
			}
			output.Success(results)
		},
	}
	searchCmd.Flags().Int("limit", 10, "maximum number of results to return")
	searchCmd.Flags().String("hl", "en", "Google UI language (en/zh-CN/etc.) — affects DOM stability")
	rootCmd.AddCommand(searchCmd)
}

package search

import (
	"context"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"

	"scholar-cli/paper"
)

type Source interface {
	Name() string
	Search(ctx context.Context, query string, limit int) ([]paper.Paper, error)
}

type SearchResult struct {
	Papers  []paper.Paper    `json:"papers"`
	Total   int              `json:"total"`
	Sources []SourceSummary  `json:"sources"`
}

type SourceSummary struct {
	Name  string `json:"name"`
	Count int    `json:"count"`
	Error string `json:"error,omitempty"`
}

var defaultHTTPClient = &http.Client{Timeout: 30 * time.Second}

func allEnglishSources() []Source {
	return []Source{
		NewOpenAlex(),
		NewSemanticScholar(),
		NewCrossRef(),
		NewArXiv(),
		NewPubMed(),
		NewDBLP(),
		NewBioRxiv(),
	}
}

func SearchEnglish(ctx context.Context, query string, limit int, sourceNames []string) (*SearchResult, error) {
	all := allEnglishSources()

	var sources []Source
	if len(sourceNames) > 0 {
		nameMap := make(map[string]Source)
		for _, s := range all {
			nameMap[strings.ToLower(s.Name())] = s
		}
		for _, name := range sourceNames {
			s, ok := nameMap[strings.ToLower(strings.TrimSpace(name))]
			if !ok {
				return nil, fmt.Errorf("unknown source: %s", name)
			}
			sources = append(sources, s)
		}
	} else {
		sources = all
	}

	return SearchAll(ctx, sources, query, limit)
}

func SearchAll(ctx context.Context, sources []Source, query string, limit int) (*SearchResult, error) {
	type sourceResult struct {
		name   string
		papers []paper.Paper
		err    error
	}

	results := make([]sourceResult, len(sources))
	var wg sync.WaitGroup

	for i, src := range sources {
		wg.Add(1)
		go func(idx int, s Source) {
			defer wg.Done()
			papers, err := s.Search(ctx, query, limit)
			results[idx] = sourceResult{name: s.Name(), papers: papers, err: err}
		}(i, src)
	}

	wg.Wait()

	var allPapers []paper.Paper
	var summaries []SourceSummary

	for _, r := range results {
		summary := SourceSummary{Name: r.name, Count: len(r.papers)}
		if r.err != nil {
			summary.Error = r.err.Error()
		}
		summaries = append(summaries, summary)
		allPapers = append(allPapers, r.papers...)
	}

	deduped := paper.Deduplicate(allPapers)

	return &SearchResult{
		Papers:  deduped,
		Total:   len(deduped),
		Sources: summaries,
	}, nil
}

