}

// Evaluate runs JS and returns the wrapped {type, value} payload.
// Caller typically parses .value into the expected shape.
func (c *Client) Evaluate(code string) (json.RawMessage, error) {
	return c.Call("evaluate", map[string]any{"code": code})
}

// EvaluateValue runs JS and unmarshals the returned expression's value into v.
// The daemon wraps evaluate results as {"type": "...", "value": <json>}.
func (c *Client) EvaluateValue(code string, v any) error {
	raw, err := c.Evaluate(code)
	if err != nil {
		return err
	}
	var wrap struct {
		Type  string          `json:"type"`
		Value json.RawMessage `json:"value"`
	}
	if err := json.Unmarshal(raw, &wrap); err != nil {
		return fmt.Errorf("parse evaluate wrapper: %w", err)
	}
	if len(wrap.Value) == 0 {
		return fmt.Errorf("evaluate returned no value (type=%s)", wrap.Type)
	}
	if err := json.Unmarshal(wrap.Value, v); err != nil {
		return fmt.Errorf("parse evaluate value: %w (raw=%s)", err, string(wrap.Value))
	}
	return nil
}

package browser

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"time"
)

const DefaultDaemonURL = "http://127.0.0.1:10086"

type Client struct {
	baseURL  string
	session  string
	http     *http.Client
	activate ActivateMode
}

func NewClient(session string) *Client {
	return &Client{
		baseURL:  DefaultDaemonURL,
		session:  session,
		http:     &http.Client{Timeout: 90 * time.Second},
		activate: defaultActivateMode(),
	}
}

func (c *Client) Call(action string, args map[string]any) (json.RawMessage, error) {
	body, _ := json.Marshal(map[string]any{
		"action":  action,
		"session": c.session,
		"args":    args,
	})
	resp, err := c.http.Post(c.baseURL+"/command", "application/json", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("daemon unreachable: %w", err)
	}
	defer resp.Body.Close()
	var result struct {
		OK    bool            `json:"ok"`
		Data  json.RawMessage `json:"data"`
		Error *struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, err
	}
	if !result.OK {
		if result.Error != nil {
			return nil, fmt.Errorf("%s: %s", result.Error.Code, result.Error.Message)
		}
		return nil, fmt.Errorf("unknown error")
	}
	return result.Data, nil
}

func (c *Client) Navigate(url string) error {
	_, err := c.Call("navigate", map[string]any{"url": url})
	if err != nil {
		return err
	}
	c.Activate()
	return nil
}

func (c *Client) NavigateNewTab(url string) error {
	_, err := c.Call("navigate", map[string]any{"url": url, "newTab": true})
	if err != nil && strings.Contains(err.Error(), "No tab with given id") {
		c.session = fmt.Sprintf("%s_%d", c.session, rand.Intn(9000)+1000)
		_, err = c.Call("navigate", map[string]any{"url": url, "newTab": true})
	}
	if err != nil {
		return err
	}
	c.Activate()
	return nil
}

func (c *Client) Evaluate(code string) (json.RawMessage, error) {
	return c.Call("evaluate", map[string]any{"code": code})
}

func (c *Client) Snapshot() (json.RawMessage, error) {
	return c.Call("snapshot", nil)
}

func (c *Client) EvaluateJSON(code string) (json.RawMessage, error) {
	data, err := c.Evaluate(code)
	if err != nil {
		return nil, err
	}
	var envelope struct {
		Type  string          `json:"type"`
		Value json.RawMessage `json:"value"`
	}
	if err := json.Unmarshal(data, &envelope); err == nil && envelope.Type == "string" {
		var s string
		if err := json.Unmarshal(envelope.Value, &s); err == nil {
			return json.RawMessage(s), nil
		}
	}
	return data, nil
}
